Tool result: """
Indeed Easy Apply - Captcha solving module.

Handles reCAPTCHA Enterprise Invisible solving via:
1. AudioCaptchaSolver (visible checkbox fallback)
2. 2captcha Enterprise Invisible API
3. Captcha interceptor installation
"""

import asyncio
import re
from typing import Optional
from loguru import logger

import os
TWOCAPTCHA_KEY = os.environ.get("TWOCAPTCHA_API_KEY", "")


async def extract_sitekey(page, target=None) -> Optional[str]:
    """
    Extract reCAPTCHA sitekey from page frames or JS globals.

    Three methods:
    1. URL reCAPTCHA iframe (parameter k=)
    2. JS global window.invisibleReCaptchaKey
    3. iframe src attribute via JS query
    """
    # 1. From reCAPTCHA iframe URL
    for f in page.frames:
        if "recaptcha" in f.url and ("anchor" in f.url or "enterprise" in f.url):
            m = re.search(r"[?&]k=([^&]+)", f.url)
            if m:
                logger.debug(f"sitekey from iframe URL: {m.group(1)[:20]}...")
                return m.group(1)

    # 2. From JS global (Indeed sets this)
    for ctx in ([page, target] if target else [page]):
        try:
            sk = await ctx.evaluate("window.invisibleReCaptchaKey")
            if sk and len(str(sk)) > 20:
                logger.debug(f"sitekey from JS global: {str(sk)[:20]}...")
                return str(sk)
        except Exception:
            pass

    # 3. From iframe src attribute (JS fallback)
    try:
        result = await page.evaluate("""
            () => {
                const iframes = document.querySelectorAll('iframe[src*="recaptcha"]');
                for (const f of iframes) {
                    const m = f.src.match(/[?&]k=([^&]+)/);
                    if (m) return m[1];
                }
                return null;
            }
        """)
        if result:
            logger.debug(f"sitekey from iframe src: {result[:20]}...")
            return result
    except Exception:
        pass

    return None


async def solve_visible_captcha(page, target, selector_engine=None) -> bool:
    """
    Solve reCAPTCHA Enterprise on Submit page.

    Indeed hides visible checkbox from patchright. Approach:
      1. AudioCaptchaSolver → if checkbox accessible (rare but possible)
      2. 2captcha Enterprise Invisible → main fallback
      3. _install_captcha_interceptor(page, token) → patch execute()
      4. Click Submit → Indeed calls execute() → gets token → submits
    """
    token = None

    # Attempt 1: AudioCaptchaSolver
    from src.stealth.audio_captcha_solver import AudioCaptchaSolver
    try:
        solver = AudioCaptchaSolver()
        token = await solver.solve(target)
        if not token:
            token = await solver.solve(page)
        if token:
            logger.info("✅ reCAPTCHA: AudioCaptchaSolver solved!")
    except Exception as e:
        logger.debug(f"AudioCaptchaSolver: {e}")

    # Attempt 2: 2captcha Enterprise Invisible (main fallback)
    if not token:
        logger.info("🔄 AudioCaptcha failed → 2captcha Enterprise Invisible...")

        sitekey = await extract_sitekey(page, target)
        if sitekey:
            token = await solve_indeed_captcha_2captcha(sitekey, page.url)
        else:
            logger.warning("⚠️ sitekey not found — 2captcha cannot be called")

    if not token:
        logger.warning("⚠️ reCAPTCHA: no method gave token")
        return False

    logger.info(f"✅ Token obtained (len={len(token)}). Installing interceptor...")

    # Install interceptor + click Submit
    await install_captcha_interceptor(page, token)
    await asyncio.sleep(_gaussian_delay(0.8, 1.5))

    # Find Submit - via SelectorEngine or legacy selectors
    from .config import IA
    _USE_SE = selector_engine is not None

    if _USE_SE:
        btn_loc = await selector_engine.find(target, "submit_button", context="captcha_submit")
        if btn_loc:
            try:
                await btn_loc.click()
                logger.info("✅ Submit clicked after reCAPTCHA + interceptor! [SelectorEngine]")
                return True
            except Exception:
                try:
                    await btn_loc.click(force=True)
                    logger.info("✅ Submit clicked (force) after reCAPTCHA!")
                    return True
                except Exception:
                    pass
    else:
        SUBMIT_SELS = [
            "[data-testid='IA-NavActionBarButton-Submit']",
            "button[aria-label='Submit your application']",
            "button:has-text('Submit your application')",
            "button:has-text('Submit')",
        ]
        for sel in SUBMIT_SELS:
            try:
                btn = target.locator(sel).first
                if await btn.count() > 0 and await btn.is_visible():
                    try:
                        await btn.click()
                    except Exception:
                        await btn.click(force=True)
                    logger.info("✅ Submit clicked after reCAPTCHA + interceptor!")
                    return True
            except Exception:
                pass

    logger.warning("⚠️ Submit button not found after reCAPTCHA")
    return False


async def solve_indeed_captcha_2captcha(sitekey: str, page_url: str) -> Optional[str]:
    """
    Solve reCAPTCHA Enterprise Invisible via 2captcha.

    IMPORTANT parameters:
      enterprise=1  — use Enterprise endpoint Google
      invisible=1    — invisible mode (no visible checkbox)

    Without invisible=1, 2captcha sends token for v2 checkbox,
    which Google rejects for invisible.
    """
    import httpx
    if not TWOCAPTCHA_KEY:
        return None

    logger.info(f"   📤 2captcha: sending task (enterprise+invisible)...")
    logger.info(f"   sitekey: {sitekey}")
    logger.info(f"   pageurl: {page_url[:60]}...")

    async with httpx.AsyncClient(timeout=180) as client:
        # Step 1: Submit task
        try:
            payload = {
                "key": TWOCAPTCHA_KEY,
                "method": "userrecaptcha",
                "googlekey": sitekey,
                "pageurl": page_url,
                "enterprise": 1,   # reCAPTCHA Enterprise
                "invisible": 1,    # invisible mode (CRITICAL for Indeed!)
                "json": 1,
            }
            resp = await client.post("https://2captcha.com/in.php", data=payload)
            result = resp.json()

            if result.get("status") != 1:
                logger.error(f"   ❌ 2captcha submit error: {result}")
                return None

            captcha_id = result["request"]
            logger.info(f"   ✓ Task #{captcha_id} accepted. Waiting for solution...")

        except Exception as e:
            logger.error(f"   ❌ Error sending to 2captcha: {e}")
            return None

        # Step 2: Polling (every 5 sec, max 120 sec)
        for attempt in range(24):
            await asyncio.sleep(5)
            try:
                resp = await client.get(
                    "https://2captcha.com/res.php",
                    params={
                        "key": TWOCAPTCHA_KEY,
                        "action": "get",
                        "id": captcha_id,
                        "json": 1,
                    }
                )
                result = resp.json()

                if result.get("status") == 1:
                    token = result["request"]
                    elapsed = (attempt + 1) * 5
                    logger.success(f"   ✅ Token obtained in ~{elapsed}s!")
                    return token

                req = result.get("request", "")
                if req.startswith("ERROR"):
                    logger.error(f"   ❌ 2captcha error: {result}")
                    return None
                # "CAPCHA_NOT_READY" — continue waiting

            except Exception as e:
                logger.debug(f"   Polling {attempt+1}: {e}")

        logger.error("   ❌ Timeout: token not obtained in 120 seconds")
        return None


async def install_captcha_interceptor(page, token: str):
    """
    Install token interceptor BEFORE clicking Submit.

    Patches grecaptcha.enterprise.execute() so when called
    it returns our pre-solved token instead of requesting from Google.

    This works because:
    1. Indeed calls grecaptcha.enterprise.execute(sitekey, {action})
    2. Function returns Promise with token
    3. Indeed passes token to their API for validation
    4. We return real token from 2captcha — Google validates it!

    IMPORTANT: call IMMEDIATELY before clicking Submit!
    Token is valid ~2 minutes.
    """
    logger.info("🔧 Installing grecaptcha.enterprise.execute() interceptor...")

    # Escape token for safe JS insertion
    safe_token = token.replace("'", "\\'").replace("\\", "\\\\")

    await page.evaluate(f"""
        (function() {{
            var TOKEN = '{safe_token}';

            // 1. Direct patch if grecaptcha already loaded
            function patchNow() {{
                if (window.grecaptcha && window.grecaptcha.enterprise) {{
                    var orig = window.grecaptcha.enterprise.execute;
                    window.grecaptcha.enterprise.execute = function(sitekey, options) {{
                        console.log('[🔑 CAPTCHA PATCH] execute() intercepted → returning pre-solved token');
                        return Promise.resolve(TOKEN);
                    }};
                    // Also patch ready callback if exists
                    if (typeof window.grecaptcha.enterprise.ready === 'function') {{
                        var origReady = window.grecaptcha.enterprise.ready;
                        // ready stays as is, just execute is patched
                    }}
                    console.log('[🔑 CAPTCHA PATCH] Installed successfully!');
                    return true;
                }}
                return false;
            }}

            if (!patchNow()) {{
                // 2. If not yet loaded — wait via MutationObserver
                console.log('[🔑 CAPTCHA PATCH] grecaptcha not yet loaded, installing observer...');
                var observer = new MutationObserver(function(mutations) {{
                    if (window.grecaptcha && window.grecaptcha.enterprise) {{
                        patchNow();
                        observer.disconnect();
                    }}
                }});
                observer.observe(document.documentElement, {{childList: true, subtree: true}});

                // 3. Also redefine Object.defineProperty to catch
                //    moment when grecaptcha.enterprise appears
                var origDefineProperty = Object.defineProperty;
                Object.defineProperty = function(obj, prop, descriptor) {{
                    var result = origDefineProperty.apply(this, arguments);
                    if (prop === 'enterprise' || prop === 'grecaptcha') {{
                        setTimeout(patchNow, 50);
                    }}
                    return result;
                }};
            }}

            // 4. Also insert token into standard textareas (v2 fallback)
            var textareas = document.querySelectorAll('#g-recaptcha-response, textarea[name="g-recaptcha-response"]');
            textareas.forEach(function(ta) {{
                ta.value = TOKEN;
                ta.innerHTML = TOKEN;
            }});

            // 5. Call ___grecaptcha_cfg callbacks if present (v2 fallback)
            try {{
                if (window.___grecaptcha_cfg) {{
                    Object.values(window.___grecaptcha_cfg.clients || {{}}).forEach(function(c) {{
                        Object.values(c).forEach(function(obj) {{
                            if (obj && typeof obj.callback === 'function') {{
                                try {{ obj.callback(TOKEN); }} catch(e) {{}}
                            }}
                        }});
                    }});
                }}
            }} catch(e) {{}}

        }})();
    """)
    logger.info("   ✓ Interceptor installed!")


def _gaussian_delay(mean: float, std: float) -> float:
    """Generate random delay with Gaussian distribution."""
    import random
    return max(0.1, random.gauss(mean, std))
